const html = String($json.body || $json.data || '').slice(0, 50000);
const hasViewport = /<meta[^>]+name=["']viewport["']/i.test(html);
const hasHttps = String($('Lookup prospect').first().json.website_url || '').startsWith('https://');
const cmsHints = [
  ['wordpress', /wp-content|wp-includes|wordpress/i],
  ['wix',       /wixstatic|wix\.com/i],
  ['squarespace', /squarespace/i],
  ['shopify',   /cdn\.shopify/i],
  ['custom',    /(?:)/]
];
let cms = 'unknown';
for (const [name, re] of cmsHints) { if (re.test(html)) { cms = name; break; } }
const yearMatch = html.match(/(?:©|copyright)\s*(20\d{2})/i);
const lastYear = yearMatch ? Number(yearMatch[1]) : null;
const snippets = [];
const homeExcerpt = html.replace(/<script[\s\S]*?<\/script>/g,'').replace(/<style[\s\S]*?<\/style>/g,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0, 800);
if (homeExcerpt) snippets.push({ id: 'home_html', url: $('Lookup prospect').first().json.website_url || '', extract: homeExcerpt });
return [{ json: {
  prospect: $('Lookup prospect').first().json,
  website_signals: { has_viewport: hasViewport, has_https: hasHttps, cms_hint: cms, last_visible_year: lastYear, html_size: html.length },
  snippets
}}];

const ctx = $('Extract signals + snippets').first().json;
const niche = String(ctx.prospect.niche || '').toLowerCase();
const memHits = ($('Memory: niche hits').first() && $('Memory: niche hits').first().json && $('Memory: niche hits').first().json.results) || [];
const patterns = $('Read memory_patterns').all().map(i=>i.json).filter(p => String(p.niche || '').toLowerCase() === niche || String(p.niche || '').toLowerCase() === 'all').slice(0, 8);
return [{ json: {
  prospect: ctx.prospect,
  website_signals: ctx.website_signals,
  snippets: ctx.snippets,
  memory_hits: memHits,
  patterns
}}];

const llm = $json; let r = {};
try { const c = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content; if (c) r = JSON.parse(c); } catch(e){ r = {}; }
const ctx = $('Build research payload').first().json;
const pid = ctx.prospect.id;
// Update review_queue avec champs enrichis + flag needs_human_research
return [{ json: {
  id: pid,
  status: r.needs_human_research ? 'needs_human_research' : (r.opt_out_signal ? 'rejected' : 'analyzed'),
  business_summary: r.business_summary || '',
  website_status: r.website_status || 'unknown',
  opportunity_score: r.opportunity_score || '',
  opportunity_reason: r.opportunity_reason || '',
  suggested_angle: r.suggested_angle || '',
  project_difficulty_score: r.project_difficulty_score || '',
  project_difficulty_label: r.project_difficulty_label || '',
  project_difficulty_reason: (r.evidence && r.evidence[0] && r.evidence[0].what_could_invalidate) || '',
  human_notes: 'global_confidence=' + (r.global_confidence || 0) + ' | conflicts=' + ((r.conflicts || []).join(' | ')) + ' | needs_human_research=' + !!r.needs_human_research,
  updated_at: new Date().toISOString()
}}];
